import{_ as t,o as i,c as l,a2 as o}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"12.3 触电事故的现场处理","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-3-chu-dian-shi-gu-de-xian-chang-chu-li.md","filePath":"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-3-chu-dian-shi-gu-de-xian-chang-chu-li.md","lastUpdated":1793096070000}'),n={name:"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-3-chu-dian-shi-gu-de-xian-chang-chu-li.md"};function r(e,a,s,h,d,c){return i(),l("div",null,[...a[0]||(a[0]=[o(`<h1 id="_12-3-触电事故的现场处理" tabindex="-1">12.3 触电事故的现场处理 <a class="header-anchor" href="#_12-3-触电事故的现场处理" aria-label="Permalink to &quot;12.3 触电事故的现场处理&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>发现有人触电,<strong>第一步不是救人,是&quot;断电&quot;</strong>。这一节掌握触电急救的三原则:迅速脱离电源、就地抢救、坚持不中断。这是实操考核必考、也是救命的关键技能。</p><h2 id="一、触电急救总原则-必背" tabindex="-1">一、触电急救总原则(必背) <a class="header-anchor" href="#一、触电急救总原则-必背" aria-label="Permalink to &quot;一、触电急救总原则(必背)&quot;">​</a></h2><ol><li><strong>迅速脱离电源</strong>——救人先断源;</li><li><strong>就地抢救</strong>——在事故现场立即进行急救,不乱搬动;</li><li><strong>坚持不断</strong>——抢救要持续进行,直到专业救护人员赶到。</li></ol><blockquote><p>💡 记住:&quot;快、就地、坚持&quot;三字诀。</p></blockquote><h2 id="二、怎样使触电者脱离电源-分情况" tabindex="-1">二、怎样使触电者脱离电源(分情况) <a class="header-anchor" href="#二、怎样使触电者脱离电源-分情况" aria-label="Permalink to &quot;二、怎样使触电者脱离电源(分情况)&quot;">​</a></h2><h3 id="_1-电源开关就在附近" tabindex="-1">1. 电源开关就在附近 <a class="header-anchor" href="#_1-电源开关就在附近" aria-label="Permalink to &quot;1. 电源开关就在附近&quot;">​</a></h3><p><strong>立即拉闸断电</strong>——最安全、最彻底。</p><h3 id="_2-开关够不着-不能拉闸" tabindex="-1">2. 开关够不着 / 不能拉闸 <a class="header-anchor" href="#_2-开关够不着-不能拉闸" aria-label="Permalink to &quot;2. 开关够不着 / 不能拉闸&quot;">​</a></h3><p>用<strong>绝缘物(干燥的木棍、竹竿、干燥木板、塑料棒)<strong>挑开电线,或</strong>垫在触电者身下</strong>使其与带电体分离:</p><ul><li>千万不要用手直接去拉触电者(会一起触电);</li><li>可<strong>戴绝缘手套</strong>或用干燥衣服裹手后再拉。</li></ul><h3 id="_3-低压触电的常用做法" tabindex="-1">3. 低压触电的常用做法 <a class="header-anchor" href="#_3-低压触电的常用做法" aria-label="Permalink to &quot;3. 低压触电的常用做法&quot;">​</a></h3><ul><li><strong>拉</strong>:拉闸断电;</li><li><strong>挑</strong>:用绝缘棒挑开电线;</li><li><strong>垫</strong>:在触电者身下垫干燥木板等隔离;</li><li>实在不行,<strong>戴绝缘手套</strong>拉开触电者(注意绝缘防护)。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>触电急救流程:</span></span>
<span class="line"><span>发现触电 ──► 立即断电(拉闸/挑线/垫绝缘物) ──► 就地检查、抢救 ──► 呼救120/打急救</span></span></code></pre></div><h2 id="三、救护者的自我保护-必考" tabindex="-1">三、救护者的自我保护(必考) <a class="header-anchor" href="#三、救护者的自我保护-必考" aria-label="Permalink to &quot;三、救护者的自我保护(必考)&quot;">​</a></h2><ul><li><strong>绝不可徒手直接拉触电者</strong>,必须用绝缘物隔离;</li><li>救护时站在<strong>干燥的木板、绝缘垫</strong>上,避免自己成为导电通路;</li><li>挑电线时用干燥绝缘物,不触碰裸露金属;</li><li>高压触电(1kV 以上)时,不能随意靠近,由专业人员用专用工具处理。</li></ul><blockquote><p>⚠️ 判断题高频:发现低压触电,<strong>不能用手直接拉</strong>,要用绝缘物或用绝缘手套;救护者自身也要绝缘防护。</p></blockquote><h2 id="四、脱离电源后的处置" tabindex="-1">四、脱离电源后的处置 <a class="header-anchor" href="#四、脱离电源后的处置" aria-label="Permalink to &quot;四、脱离电源后的处置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>处理</th></tr></thead><tbody><tr><td>触电者<strong>神志清醒</strong></td><td>就地休息,观察,必要时送医(不要马上走动)</td></tr><tr><td>触电者<strong>昏迷但有心跳呼吸</strong></td><td>解开衣领、保持呼吸道通畅,侧卧,呼救 120</td></tr><tr><td>触电者<strong>心跳呼吸停止</strong></td><td>立即进行<strong>心肺复苏(CPR)</strong>,同时呼救(见 12.4)</td></tr></tbody></table><blockquote><p>⚠️ 注意:<strong>触电者脱离电源后,即使已经停止呼吸心跳,也仍有抢救成功的可能</strong>——要坚持抢救,不能轻易放弃。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 触电急救三原则:迅速脱离电源、就地抢救、坚持不断。</li><li>✅ 脱离电源:拉闸、挑开、垫绝缘物;<strong>禁止徒手拉人</strong>。</li><li>✅ 救护者做好绝缘防护。</li><li>⚠️ 易混点:先救人?不——<strong>先断电</strong>,断电才是保护触电者又保护救护者的前提。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>发现触电:先断电,再抢救,就地、坚持。</li><li>用绝缘物挑线、垫身,严禁徒手拉人。</li><li>断电后按神志/呼吸心跳情况分级处理。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)发现有人触电,首先应设法使触电者脱离电源。( )</li><li>(判断)抢救低压触电者时,可以用手直接拉触电者使其离开电源。( )</li><li>(单选)使触电者脱离电源,下列做法正确的是()。 A. 用手直接拉　B. 用干燥木棍挑开电线　C. 用湿木棍　D. 用金属棒</li><li>(判断)触电者脱离电源后心跳呼吸停止,应立即进行心肺复苏并坚持抢救。( )</li><li>(单选)救护触电者时,救护者应()。 A. 站在湿地上　B. 做好绝缘防护(站干燥木板、戴绝缘手套)　C. 用手触摸触电者皮肤　D. 直接抓电线</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。先使触电者脱离电源。</li><li><strong>×</strong>。严禁徒手直接拉,易一起触电。</li><li><strong>B</strong>。用干燥绝缘物挑开电线。</li><li><strong>√</strong>。立即心肺复苏并坚持抢救。</li><li><strong>B</strong>。救护者要绝缘防护。</li></ol></details>`,28)])])}const p=t(n,[["render",r]]);export{g as __pageData,p as default};
